"""Render a Claude Code Statusline Designer config into a Claude Code statusline bash script."""
from claude_style.validate import validate_config

HEADER = """#!/usr/bin/env bash
# Generated by Claude Code Statusline Designer -- do not edit by hand; run `claude-style` to change it.
# Preset: {preset} | separator: {separator}
input=$(cat)

user=$(whoami)
host=$(hostname -s)
dir=$(echo "$input" | jq -r '.workspace.current_dir // .cwd')
model=$(echo "$input" | jq -r '.model.display_name // "Claude"')
effort=$(echo "$input" | jq -r '.effort.level // empty')
used=$(echo "$input" | jq -r '.context_window.used_percentage // empty')
outstyle=$(echo "$input" | jq -r '.output_style.name // empty')
cost_usd=$(echo "$input" | jq -r '.cost.total_cost_usd // 0')
duration_ms=$(echo "$input" | jq -r '.cost.total_duration_ms // 0')

home_dir="$HOME"
short_dir="${{dir/#$home_dir/\\~}}"

branch=$(git -C "$dir" --no-optional-locks symbolic-ref --short HEAD 2>/dev/null)
git_status=""
if [ -n "$branch" ]; then
  git_status=$(git -C "$dir" --no-optional-locks status --porcelain --ignore-submodules=dirty --untracked-files=normal 2>/dev/null)
fi

RESET=$'\\033[0m'

# Both accept either a plain 256-color number ("130") or a true-color spec
# ("rgb:R,G,B"), so any segment color can transparently be a gradient value.
fg() {{
  case "$1" in
    rgb:*) local spec="${{1#rgb:}}"; local r="${{spec%%,*}}" rest="${{spec#*,}}"
           printf '\\033[38;2;%s;%s;%sm' "$r" "${{rest%%,*}}" "${{rest#*,}}" ;;
    *) printf '\\033[38;5;%sm' "$1" ;;
  esac
}}
bg() {{
  case "$1" in
    rgb:*) local spec="${{1#rgb:}}"; local r="${{spec%%,*}}" rest="${{spec#*,}}"
           printf '\\033[48;2;%s;%s;%sm' "$r" "${{rest%%,*}}" "${{rest#*,}}" ;;
    *) printf '\\033[48;5;%sm' "$1" ;;
  esac
}}

supports_truecolor() {{
  case "${{COLORTERM:-}}" in truecolor|24bit) return 0 ;; esac
  return 1
}}

# $1 = percentage 0-100 -> sets GR GG GB (green -> yellow -> red).
# GRADIENT_PEAK caps the channels: 255 glows on dark terminals, ~180 stays readable on light ones.
gradient_rgb() {{
  local p=$1 peak=${{GRADIENT_PEAK:-255}}
  if [ "$p" -le 50 ]; then GR=$(( p * peak / 50 )); GG=$peak
  else GR=$peak; GG=$(( peak - (p - 50) * peak / 50 ))
  fi
  GB=0
}}
"""

POWERLINE_HELPERS = """
SEP=$'\\ue0b0'
sep() { fg "$1"; bg "$2"; printf '%s' "$SEP"; }
sep_end() { fg "$1"; printf '\\033[49m%s%s' "$SEP" "$RESET"; }
prev=""
"""

PLAIN_HELPERS = """
plain_sep() { printf ' \\033[34m|\\033[0m '; }
first=1
plain_join() { [ "$first" -eq 0 ] && plain_sep; first=0; }
"""


def _effort_case(colors: dict) -> str:
    lines = ["case \"$effort\" in"]
    for level in ("low", "medium", "high", "xhigh", "max"):
        if level in colors:
            lines.append(f'  {level}) C_EFFORT={colors[level]} ;;')
    lines.append(f'  *) C_EFFORT={colors.get("default", 239)} ;;')
    lines.append("esac")
    return "\n".join(lines)


def _threshold_ladder(thresholds: list, indent: str = "  ") -> list:
    lines = []
    sorted_th = sorted(thresholds, key=lambda t: t[0])
    for i, (limit, color) in enumerate(sorted_th):
        kw = "if" if i == 0 else "elif"
        lines.append(f"{indent}{kw} [ \"$used_int\" -lt {limit} ]; then C_CTX={color}")
    lines.append(f"{indent}fi")
    return lines


def _dir_shorten_logic(dir_cfg: dict) -> str:
    narrow = dir_cfg.get("narrow_cols", 60)
    medium = dir_cfg.get("medium_cols", 100)
    segments = dir_cfg.get("medium_segments", 2)
    # NF>n: keep only the last n path parts, prefixed with "..." so a split
    # terminal (e.g. tmux panes) still shows the tail of the path, not junk.
    awk_script = (
        '{ if (NF > n) { s = ""; for (i = NF - n + 1; i <= NF; i++) s = s "/" $i; print "..." s } else print $0 }'
    )
    return (
        'cols="${COLUMNS:-80}"\n'
        f'if [ "$cols" -lt {narrow} ]; then\n'
        '  short_dir=$(basename "$short_dir")\n'
        f'elif [ "$cols" -lt {medium} ]; then\n'
        f"  short_dir=$(printf '%s' \"$short_dir\" | awk -F/ -v n={segments} '{awk_script}')\n"
        "fi"
    )


def _context_color_logic(context_cfg: dict) -> str:
    lines = [
        f"GRADIENT_PEAK={context_cfg['gradient_peak']}",
        "if [ -n \"$used\" ]; then",
        "  used_int=$(LC_NUMERIC=C printf '%.0f' \"$used\")",
    ]
    if context_cfg.get("true_color", True):
        lines.append("  if supports_truecolor; then")
        lines.append(f"    C_CTX={context_cfg['bar_bg']}  # neutral background; the bar itself carries the gradient")
        lines.append("    CTX_TRUECOLOR=1")
        lines.append("  else")
        lines.extend(_threshold_ladder(context_cfg["thresholds"], indent="    "))
        lines.append("    CTX_TRUECOLOR=0")
        lines.append("  fi")
    else:
        lines.extend(_threshold_ladder(context_cfg["thresholds"], indent="  "))
        lines.append("  CTX_TRUECOLOR=0")
    lines.append("fi")
    return "\n".join(lines)


def render(config: dict) -> str:
    validate_config(config)
    seg = config["segments"]
    separator = config.get("separator", "powerline")
    powerline = separator == "powerline"

    parts = [HEADER.format(preset=config.get("preset", "custom"), separator=separator)]
    parts.append(POWERLINE_HELPERS if powerline else PLAIN_HELPERS)

    if seg["effort"]["enabled"]:
        parts.append(_effort_case(seg["effort"]["colors"]))
    if seg["context"]["enabled"]:
        parts.append(_context_color_logic(seg["context"]))
    if seg["dir"]["enabled"] and seg["dir"].get("responsive", True):
        parts.append(_dir_shorten_logic(seg["dir"]))

    body = []

    # --- user@host ---
    if seg["user_host"]["enabled"]:
        c = seg["user_host"]
        if powerline:
            body.append(f'bg {c["bg"]}; fg {c["fg"]}')
            body.append('printf " %s@%s " "$user" "$host"')
            body.append(f'prev={c["bg"]}')
        else:
            body.append('plain_join')
            body.append(f'fg {c["fg"]}; printf "%s@%s" "$user" "$host"; printf "$RESET"')

    # --- dir ---
    if seg["dir"]["enabled"]:
        c = seg["dir"]
        if powerline:
            body.append(f'sep "$prev" {c["bg"]}')
            body.append(f'fg {c["fg"]}')
            body.append('printf " %s " "$short_dir"')
            body.append(f'prev={c["bg"]}')
        else:
            body.append('plain_join')
            body.append(f'fg {c["fg"]}; printf "%s" "$short_dir"; printf "$RESET"')

    # --- git ---
    if seg["git"]["enabled"]:
        c = seg["git"]
        body.append('if [ -n "$branch" ]; then')
        if powerline:
            body.append('  if [ -n "$git_status" ]; then')
            body.append(f'    next={c["bg_dirty"]}; dirty_glyph=" \\xc2\\xb1"')
            body.append('  else')
            body.append(f'    next={c["bg_clean"]}; dirty_glyph=""')
            body.append('  fi')
            body.append('  sep "$prev" "$next"')
            body.append(f'  fg {c["fg"]}')
            body.append('  printf " \\xef\\x90\\x9c %s%b " "$branch" "$dirty_glyph"')
            body.append('  prev=$next')
        else:
            body.append('  plain_join')
            body.append('  if [ -n "$git_status" ]; then')
            body.append(f'    fg {c["bg_dirty"]}')
            body.append('  else')
            body.append(f'    fg {c["bg_clean"]}')
            body.append('  fi')
            body.append('  printf "\\xef\\x90\\x9c %s" "$branch"; printf "$RESET"')
        body.append('fi')

    # --- model + effort ---
    if seg["model"]["enabled"]:
        c = seg["model"]
        if powerline:
            body.append(f'sep "$prev" {c["bg"]}')
            body.append(f'fg {c["fg"]}')
            body.append('printf " %s" "$model"')
            body.append(f'prev={c["bg"]}')
        else:
            body.append('plain_join')
            body.append(f'fg {c["fg"]}; printf "%s" "$model"; printf "$RESET"')

    if seg["effort"]["enabled"]:
        ec = seg["effort"]
        body.append('if [ -n "$effort" ]; then')
        if powerline:
            body.append('  sep "$prev" "$C_EFFORT"')
            body.append(f'  fg {ec["fg"]}')
            body.append('  printf " %s " "$effort"')
            body.append('  prev=$C_EFFORT')
        else:
            body.append('  printf "/"')
            body.append('  fg "$C_EFFORT"; printf "%s" "$effort"; printf "$RESET"')
        body.append('fi')
    if powerline and seg["model"]["enabled"] and not seg["effort"]["enabled"]:
        body.append('printf " "')

    # --- output style (only shown when not "default") ---
    if seg["output_style"]["enabled"]:
        c = seg["output_style"]
        body.append('if [ -n "$outstyle" ] && [ "$outstyle" != "default" ]; then')
        if powerline:
            body.append(f'  sep "$prev" {c["bg"]}')
            body.append(f'  fg {c["fg"]}')
            body.append('  printf " %s " "$outstyle"')
            body.append(f'  prev={c["bg"]}')
        else:
            body.append('  plain_join')
            body.append(f'  fg {c["fg"]}; printf "style:%s" "$outstyle"; printf "$RESET"')
        body.append('fi')

    # --- context usage ---
    if seg["context"]["enabled"]:
        style = seg["context"].get("style", "bar")
        cf = seg["context"]["fg"]
        empty_fg = seg["context"]["bar_empty"]
        # Without true color: in powerline mode the threshold color is the segment
        # background, so the bar/number uses the text color; in plain mode there is
        # no background, so the threshold color itself is drawn.
        fallback_fg = cf if powerline else '"$C_CTX"'
        body.append('if [ -n "$used" ]; then')
        if powerline:
            body.append('  sep "$prev" "$C_CTX"')
            body.append(f'  fg {cf}')
        else:
            body.append('  plain_join')
            body.append('  fg "$C_CTX"')
        if style == "bar":
            body.append('  filled=$(( used_int / 10 )); [ "$filled" -gt 10 ] && filled=10')
            body.append('  printf " "')
            body.append('  for i in $(seq 1 10); do')
            body.append('    if [ "$i" -le "$filled" ]; then')
            body.append('      if [ "$CTX_TRUECOLOR" = "1" ]; then')
            body.append('        gradient_rgb $(( i * 10 - 5 )); fg "rgb:${GR},${GG},${GB}"')
            body.append('      else')
            body.append(f'        fg {fallback_fg}')
            body.append('      fi')
            body.append('      printf "\\xe2\\x96\\x88"')
            body.append('    else')
            body.append(f'      fg {empty_fg}; printf "\\xe2\\x96\\x91"')
            body.append('    fi')
            body.append('  done')
            body.append(f'  fg {cf}')
            if powerline:
                body.append('  printf " %d%% " "$used_int"')
            else:
                body.append('  printf " %d%%" "$used_int"; printf "$RESET"')
        else:
            body.append('  if [ "$CTX_TRUECOLOR" = "1" ]; then')
            body.append('    gradient_rgb "$used_int"; fg "rgb:${GR},${GG},${GB}"')
            body.append('  else')
            body.append(f'    fg {fallback_fg}')
            body.append('  fi')
            if powerline:
                body.append('  printf " ctx %d%% " "$used_int"')
            else:
                body.append('  printf "ctx %d%%" "$used_int"; printf "$RESET"')
        if powerline:
            body.append('  prev=$C_CTX')
        body.append('fi')

    # --- cost ---
    if seg["cost"]["enabled"]:
        cc = seg["cost"]
        guard = 'awk -v c="$cost_usd" \'BEGIN { exit !(c > 0) }\'' if cc.get("hide_zero", True) else 'true'
        body.append(f'if {guard}; then')
        body.append(f'  if awk -v c="$cost_usd" -v t="{cc.get("warn_threshold_usd", 5.0)}" \'BEGIN {{ exit !(c > t) }}\'; then')
        body.append(f'    C_COST={cc["colors"]["warn"]}')
        body.append('  else')
        body.append(f'    C_COST={cc["colors"]["normal"]}')
        body.append('  fi')
        if powerline:
            body.append('  sep "$prev" "$C_COST"')
            body.append(f'  fg {cc["fg"]}')
            body.append('  LC_NUMERIC=C printf " $%.2f " "$cost_usd"')
            body.append('  prev=$C_COST')
        else:
            body.append('  plain_join')
            body.append('  fg "$C_COST"; LC_NUMERIC=C printf "$%.2f" "$cost_usd"; printf "$RESET"')
        body.append('fi')

    # --- duration ---
    if seg["duration"]["enabled"]:
        dc = seg["duration"]
        guard = '[ "$duration_ms" -gt 0 ]' if dc.get("hide_zero", True) else 'true'
        body.append(f'if {guard}; then')
        body.append('  d_sec=$((duration_ms / 1000)); d_min=$((d_sec / 60)); d_h=$((d_min / 60))')
        body.append('  if [ "$d_h" -gt 0 ]; then d_fmt="${d_h}h$((d_min % 60))m"; else d_fmt="${d_min}m$((d_sec % 60))s"; fi')
        if powerline:
            body.append(f'  sep "$prev" {dc["bg"]}')
            body.append(f'  fg {dc["fg"]}')
            body.append('  printf " %s " "$d_fmt"')
            body.append(f'  prev={dc["bg"]}')
        else:
            body.append('  plain_join')
            body.append(f'  fg {dc["fg"]}; printf "%s" "$d_fmt"; printf "$RESET"')
        body.append('fi')

    parts.append("\n".join(body))

    if powerline:
        parts.append('[ -n "$prev" ] && sep_end "$prev"')

    return "\n\n".join(parts) + "\n"
